import Phaser from "phaser";
import { gearDef, itemText, LOOT_IDS, canWear, GEAR_SLOTS, gearName, gearStats, gearSpeedMult, GearSlot, BAG_SIZE, SLOT_NAMES, TIER_NAMES, baseId, itemRarity, RARITY_NAMES, affixLines, itemLevel, reqProblem, reqText, activeGear, HeroReqInfo, Equipped } from "../../shared/gear";
import { STAT_NAMES, StatKind } from "../../shared/powers";
import { ART_K, CHAR_FRAME, HD_CHARS } from "./artAssets";

/**
 * Equipment on the client: overlay sprites that follow each hero frame for frame, and the equipment screen (G).
 * Overlay sheets are generated by tools/art/gear.ts with the same frame layout as the hero sheets.
 */
const GEAR_HEROES = ["ninja", "wizard", "knight", "archer", "barbarian"];
const BASE = "assets/gear";
export const TIER_COLORS = ["", "#e0e0e0", "#4cc9f0", "#c77dff"];
/** Item colour by rarity (shared/gear.ts RARITY_NAMES): Plain, Magic, Rare, Legendary. */
export const RARITY_COLORS = ["#e0e0e0", "#6f8fff", "#ffd84a", "#ff8c1a"];
export const RARITY_HEX = [0xe0e0e0, 0x6f8fff, 0xffd84a, 0xff8c1a];
export const itemColor = (id: string) => RARITY_COLORS[itemRarity(id)];
/** "Rare Fine Weapon" label, plus the random bonuses as coloured lines. */
export const rarityLabel = (id: string) => { const r = itemRarity(id); return r ? `<span style="color:${RARITY_COLORS[r]}">${RARITY_NAMES[r]}</span> ` : ""; };
export const affixHtml = (id: string) => affixLines(id).map((l) => `<span style="color:${itemColor(id)}">${l}</span>`).join("<br>");

export function preloadGear(scene: Phaser.Scene) {
  scene.load.atlas("gear_icons", `${BASE}/icons.png`, `${BASE}/icons.json`);
  // Painted overlay sheets are big (96px frames), so they load the first time someone wears the item
  if (HD_CHARS) return;
  for (const h of GEAR_HEROES) for (const id of LOOT_IDS) { // the old pixel sheets already show the class kit
    scene.load.spritesheet(gearKey(h, id), `${BASE}/${h}_${id}.png`, { frameWidth: CHAR_FRAME, frameHeight: CHAR_FRAME });
  }
}

const pending = new Set<string>();
/** Starts loading a painted overlay sheet if it is not there yet; returns true when it can be used. */
function ensureGear(scene: Phaser.Scene, hero: string, id: string, done?: () => void) {
  const key = gearKey(hero, id);
  if (scene.textures.exists(key)) return true;
  if (!HD_CHARS || pending.has(key) || !GEAR_HEROES.includes(hero.split("-")[0])) return false; // "archer-melee": a stance sheet
  pending.add(key);
  scene.load.spritesheet(key, `assets/hd/gear/${hero}_${baseId(id)}.webp`, { frameWidth: CHAR_FRAME, frameHeight: CHAR_FRAME });
  scene.load.once(`filecomplete-spritesheet-${key}`, () => {
    pending.delete(key);
    scene.textures.get(key).setFilter(Phaser.Textures.FilterMode.NEAREST); // pixel art: keep texels crisp
    done?.();
  });
  scene.load.once("loaderror", () => pending.delete(key));
  if (!scene.load.isLoading()) scene.load.start();
  return false;
}

/** Overlay texture of an item on a hero (every item level of an item looks the same; gearfx.ts adds the effects). */
export const gearKey = (hero: string, id: string) => `gear_${hero}_${baseId(id)}`;

/** Level and own stat points of a hero state, for the item requirements. */
export const reqInfoOf = (state: any): HeroReqInfo =>
  ({ cls: state.cls, level: state.level ?? 1, pts: { sta: state.ptSta ?? 0, str: state.ptStr ?? 0, mag: state.ptMag ?? 0, dex: state.ptDex ?? 0 } });

/** The worn items that count for a hero state (requirements met). */
export const activeOf = (state: any): Equipped => activeGear(Object.fromEntries(GEAR_SLOTS.map((s) => [s, state[s]])), reqInfoOf(state));

/**
 * Drawn order on top of the hero (each overlay already has the right pixels hidden behind the body).
 * The base sheet is the bare hero in underwear: armour first (clothes), then boots over the trouser legs, then the rest.
 */
export const LAYER_ORDER: GearSlot[] = ["armour", "shoes", "ranged", "hat", "shield", "weapon"];

/** Overlay sprites for one hero. Call sync() every frame after the hero sprite is updated. */
export class GearLayer {
  private sprites: Partial<Record<GearSlot, Phaser.GameObjects.Sprite>> = {};
  private ids: Partial<Record<GearSlot, string>> = {};

  constructor(private scene: Phaser.Scene, private hero: string) {}

  /** The hero changed stance (another weapon family): overlays come from that sheet's set now. */
  setHero(hero: string) {
    if (hero === this.hero) return;
    this.hero = hero;
    this.ids = {}; // re-texture every overlay on the next sync
  }

  sync(base: Phaser.GameObjects.Sprite, state: any) {
    LAYER_ORDER.forEach((slot, i) => {
      const id: string = state[slot] ?? "";
      const key = id ? gearKey(this.hero, id) : "";
      let s = this.sprites[slot];
      if (!key || !ensureGear(this.scene, this.hero, id)) {
        if (s) { s.destroy(); delete this.sprites[slot]; delete this.ids[slot]; }
        return;
      }
      if (!s) s = this.sprites[slot] = this.scene.add.sprite(base.x, base.y, key, 0);
      if (this.ids[slot] !== key) { s.setTexture(key, 0); this.ids[slot] = key; }
      s.setFrame(base.frame.name);
      s.setPosition(base.x, base.y).setOrigin(base.originX, base.originY).setScale(base.scaleX, base.scaleY);
      s.setFlipX(base.flipX).setAngle(base.angle).setAlpha(base.alpha).setVisible(base.visible);
      s.setDepth(base.depth + 0.01 * (i + 1));
      if (base.isTinted) { s.setTint(base.tintTopLeft); s.tintFill = base.tintFill; } else if (s.isTinted) s.clearTint();
    });
  }

  destroy() {
    for (const s of Object.values(this.sprites)) s?.destroy();
    this.sprites = {};
  }
}

/** Draws a frame of a Phaser texture into a 2D canvas (for the menu). */
function drawFrame(scene: Phaser.Scene, ctx: CanvasRenderingContext2D, key: string, frame: string | number, dx: number, dy: number, scale: number) {
  if (!scene.textures.exists(key)) return;
  const f = scene.textures.getFrame(key, frame);
  if (!f) return;
  ctx.drawImage(f.source.image as CanvasImageSource, f.cutX, f.cutY, f.cutWidth, f.cutHeight, dx, dy, f.cutWidth * scale, f.cutHeight * scale);
}

export function iconCanvas(scene: Phaser.Scene, id: string, size = 32): HTMLCanvasElement {
  const c = document.createElement("canvas");
  c.width = c.height = size;
  const ctx = c.getContext("2d")!;
  ctx.imageSmoothingEnabled = false;
  drawFrame(scene, ctx, "gear_icons", baseId(id), 0, 0, size / (16 * ART_K));
  return c;
}

/** The equipment screen. */
export class GearMenu {
  private el = document.getElementById("gear")!;
  private sig = "";
  private busyUntil = 0; // one action at a time: a double-click must not swap an item in and straight back out

  constructor(private scene: Phaser.Scene, private send: (type: string, msg: unknown) => void) {
    // Buttons never keep keyboard focus, so Space/Enter in a fight can't click a bag item by accident
    this.el.addEventListener("mousedown", (ev) => { if ((ev.target as HTMLElement).closest("button")) ev.preventDefault(); });
  }

  /** Sends a bag action unless the previous one is still waiting for the server's update (max 800 ms). */
  private act(type: string, msg: unknown) {
    if (performance.now() < this.busyUntil) return;
    this.busyUntil = performance.now() + 800;
    this.send(type, msg);
  }

  get open() { return !this.el.hidden; }
  /** Opens on top of any other menu; works in combat, while dead and while chatting (via the Bag button). */
  toggle(state: any) {
    if (this.open) { this.close(); return; }
    for (const id of ["hero", "tree"]) { const other = document.getElementById(id); if (other) other.hidden = true; }
    this.el.hidden = false; this.sig = ""; this.refresh(state);
  }
  close() { this.el.hidden = true; }

  /** Rebuild only when something gear-related changed. */
  refresh(state: any) {
    if (!this.open || !state) return;
    const bagItems: string[] = Array.from(state.bag ?? []);
    const sig = [state.cls, state.level, state.ptSta, state.ptStr, state.ptMag, state.ptDex, ...GEAR_SLOTS.map((s) => state[s]), ...bagItems, state.sta, state.str, state.mag, state.dex, state.maxHp].join("|");
    if (sig === this.sig) return;
    this.sig = sig;
    this.busyUntil = 0; // the server answered, accept clicks again
    const cls = state.cls as string;
    const hero = reqInfoOf(state);
    const info = document.getElementById("gearinfo");
    if (info) info.textContent = "";
    /** Item details shown under the bag on hover (pixel font, unlike a browser tooltip). */
    const hover = (el: HTMLElement, id: string, extra: string) => {
      el.onmouseenter = () => {
        if (!info) return;
        const d = gearDef(id)!, why = reqProblem(id, hero);
        const aff = affixHtml(id);
        info.innerHTML = `<b style="color:${itemColor(id)}">${gearName(id, cls)}</b> <span class="glvl">Lv ${itemLevel(id)}</span> · ${rarityLabel(id)}${TIER_NAMES[d.tier]} ${SLOT_NAMES[d.slot]}<br>` +
          `${itemText(id) || "No bonus"}<br>${aff ? `${aff}<br>` : ""}<span class="${why ? "gbad" : "gok"}">${why || reqText(id, cls)}</span>${extra ? `<br><small>${extra}</small>` : ""}`;
      };
      el.onmouseleave = () => { if (info) info.textContent = ""; };
    };

    // Hero preview with everything worn
    const pv = document.getElementById("gearpreview") as HTMLCanvasElement;
    const ctx = pv.getContext("2d")!;
    ctx.imageSmoothingEnabled = false;
    ctx.clearRect(0, 0, pv.width, pv.height);
    drawFrame(this.scene, ctx, cls, 0, 0, 0, pv.width / CHAR_FRAME);
    for (const slot of LAYER_ORDER) if (state[slot] && ensureGear(this.scene, cls, state[slot], () => { this.sig = ""; this.refresh(state); })) drawFrame(this.scene, ctx, gearKey(cls, state[slot]), 0, 0, 0, pv.width / CHAR_FRAME);

    // Slots
    const slots = document.getElementById("gearslots")!;
    slots.innerHTML = "";
    for (const slot of GEAR_SLOTS) {
      const id: string = state[slot];
      const row = document.createElement("button");
      row.className = "gslot" + (id ? "" : " empty");
      const icon = id ? iconCanvas(this.scene, id) : Object.assign(document.createElement("span"), { className: "gicon" });
      row.appendChild(icon);
      const txt = document.createElement("span");
      const why = id ? reqProblem(id, hero) : "";
      txt.innerHTML = id
        ? `<b style="color:${itemColor(id)}">${gearName(id, cls)}</b>${itemLevel(id) > 1 ? ` <span class="glvl">Lv ${itemLevel(id)}</span>` : ""}<br>` +
          (why ? `<small class="gbad">Inactive: ${why}</small>` : `<small>${itemText(id)}</small>`)
        : `<b>${SLOT_NAMES[slot]}</b><br><small>empty</small>`;
      row.appendChild(txt);
      if (id) { row.onclick = () => this.act("unequip", slot); hover(row, id, "Click to take off"); }
      slots.appendChild(row);
    }

    // Totals
    const g = gearStats(cls, activeOf(state));
    const speed = gearSpeedMult(activeOf(state));
    const parts = (["sta", "str", "mag", "dex"] as StatKind[]).filter((k) => g[k]).map((k) => `+${g[k]} ${STAT_NAMES[k]}`);
    if (speed > 1) parts.push(`+${Math.round((speed - 1) * 100)}% speed`);
    document.getElementById("geartotal")!.textContent =
      `${state.maxHp} HP · Stamina ${state.sta} · Strength ${state.str} · Magic ${state.mag} · Dexterity ${state.dex ?? 0}` + (parts.length ? `  (gear: ${parts.join(", ")})` : "");

    // Bag
    const bag = document.getElementById("gearbag")!;
    bag.innerHTML = "";
    document.getElementById("gearbagtitle")!.textContent = `Bag ${bagItems.length}/${BAG_SIZE}`;
    for (let i = 0; i < BAG_SIZE; i++) {
      const id: string | undefined = bagItems[i];
      const cell = document.createElement("button");
      cell.className = "gcell";
      if (id) {
        const d = gearDef(id)!;
        cell.appendChild(iconCanvas(this.scene, id));
        cell.style.borderColor = itemColor(id);
        if (itemRarity(id) >= 2) cell.style.boxShadow = `inset 0 0 6px ${itemColor(id)}`;
        const fits = canWear(cls, id), why = fits ? reqProblem(id, hero) : "";
        if (itemLevel(id) > 1) cell.appendChild(Object.assign(document.createElement("span"), { className: "gcelllvl" + (why ? " gbad" : ""), textContent: String(itemLevel(id)) }));
        hover(cell, id, fits ? (why ? "Too strong for you yet · Right-click: drop" : "Click: equip · Right-click: drop") : `Only a ${d.cls} can wear this · Right-click: drop`);
        if (!fits) cell.style.opacity = "0.5";
        else if (why) cell.classList.add("glocked");
        cell.onclick = () => this.act("equip", i);
        cell.oncontextmenu = (ev) => { ev.preventDefault(); this.act("dropgear", i); };
      } else cell.disabled = true;
      bag.appendChild(cell);
    }
    document.getElementById("gearempty")!.hidden = bagItems.length > 0 || GEAR_SLOTS.some((s) => state[s]);
  }
}
